cat > internal/ingest/zz_hidden_n6_test.go <<'GO'
package ingest

import "testing"

func TestJSONLCarriesDepth(t *testing.T) {
	r, ok := decoderFor("jsonl").DecodeLine([]byte(`{"name":"a","value":1,"depth":3}`))
	if !ok {
		t.Fatal("record should decode")
	}
	if r.Depth != 3 {
		t.Fatalf("depth lost: want 3, got %d", r.Depth)
	}
	if r.Name != "a" || r.Value != 1 {
		t.Fatalf("other fields disturbed: %+v", r)
	}
	if _, present := r.Labels["depth"]; present {
		t.Fatal("depth must not also land in labels")
	}
}

func TestJSONLWithoutDepthStaysZero(t *testing.T) {
	r, ok := decoderFor("jsonl").DecodeLine([]byte(`{"name":"a","value":1}`))
	if !ok || r.Depth != 0 {
		t.Fatalf("want depth 0, got %+v", r)
	}
}

func TestJSONLBadDepthDoesNotDropTheRecord(t *testing.T) {
	r, ok := decoderFor("jsonl").DecodeLine([]byte(`{"name":"a","value":1,"depth":"x"}`))
	if !ok {
		t.Fatal("a bad depth must not discard the whole record")
	}
	if r.Name != "a" {
		t.Fatalf("name lost: %+v", r)
	}
}

func TestCSVPathUnchanged(t *testing.T) {
	r, ok := decoderFor("csv").DecodeLine([]byte("a,1,env=prod"))
	if !ok || r.Name != "a" || r.Labels["env"] != "prod" {
		t.Fatalf("csv decoding disturbed: %+v", r)
	}
}
